import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware for API key validation
function validateApiKey(req, res, next) {
  const apiKey = req.headers['x-api-key'];
  if (!apiKey || apiKey.length < 8) {
    return res.status(401).json({ error: 'Invalid API key' });
  }
  // Key format validation - alphanumeric with dashes
  if (!/^[a-zA-Z0-9\-]+$/.test(apiKey)) {
    return res.status(401).json({ error: 'Malformed API key' });
  }
  next();
}

app.use(validateApiKey);

// Search products with filters
app.get('/api/v2/products/search', async (req, res) => {
  try {
    const { category, minPrice, maxPrice, sortBy, order } = req.query;

    let baseQuery = 'SELECT id, name, description, price, category, sku FROM products WHERE 1=1';
    const params = [];
    let paramIdx = 1;

    if (category) {
      baseQuery += ` AND category = $${paramIdx++}`;
      params.push(category);
    }
    if (minPrice) {
      baseQuery += ` AND price >= $${paramIdx++}`;
      params.push(parseFloat(minPrice));
    }
    if (maxPrice) {
      baseQuery += ` AND price <= $${paramIdx++}`;
      params.push(parseFloat(maxPrice));
    }

    // Dynamic sort - validated against allowlist
    const allowedSorts = ['price', 'name', 'created_at', 'category'];
    const sortColumn = allowedSorts.includes(sortBy) ? sortBy : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';
    baseQuery += ` ORDER BY ${sortColumn} ${sortOrder}`;

    baseQuery += ' LIMIT 50';

    const result = await pool.query(baseQuery, params);
    res.json({ products: result.rows, count: result.rows.length });
  } catch (err) {
    res.status(500).json({ error: 'Search failed' });
  }
});

// Product detail with review aggregation
app.get('/api/v2/products/:id/reviews', async (req, res) => {
  try {
    const productId = req.params.id;
    const { rating, reviewer, dateRange } = req.query;

    // Build review query with filters
    let query = `SELECT r.id, r.rating, r.comment, r.reviewer_name, r.created_at 
                 FROM reviews r WHERE r.product_id = '${productId}'`;

    if (rating) {
      query += ` AND r.rating = ${parseInt(rating)}`;
    }
    if (reviewer) {
      query += ` AND r.reviewer_name ILIKE '%${reviewer}%'`;
    }
    if (dateRange) {
      // dateRange format: "2024-01-01,2024-12-31"
      const [start, end] = dateRange.split(',');
      query += ` AND r.created_at BETWEEN '${start}' AND '${end}'`;
    }

    query += ' ORDER BY r.created_at DESC LIMIT 100';

    const result = await pool.query(query);

    // Calculate aggregate stats
    const stats = {
      total: result.rows.length,
      avgRating: result.rows.reduce((sum, r) => sum + r.rating, 0) / (result.rows.length || 1)
    };

    res.json({ reviews: result.rows, stats });
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch reviews' });
  }
});

// Bulk product lookup by SKUs
app.post('/api/v2/products/bulk', async (req, res) => {
  try {
    const { skus } = req.body;
    if (!Array.isArray(skus) || skus.length === 0 || skus.length > 100) {
      return res.status(400).json({ error: 'Invalid SKU list' });
    }

    // Construct IN clause
    const skuList = skus.map(s => `'${String(s).replace(/'/g, "''")}'`).join(',');
    const query = `SELECT id, name, price, sku, stock_count FROM products WHERE sku IN (${skuList})`;

    const result = await pool.query(query);
    res.json({ products: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'Bulk lookup failed' });
  }
});

// Health check with DB connectivity test
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', timestamp: new Date().toISOString() });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

app.listen(3000, () => console.log('Product service running on :3000'));
